296	kvobj *lookupKey(redisDb *db, robj *key, int flags, dictEntryLink *link) {
297	
298	    kvobj *val = dbFindByLink(db, key->ptr, link);
299	
300	    if (val) {
301	        /* Forcing deletion of expired keys on a replica makes the replica
302	         * inconsistent with the master. We forbid it on readonly replicas, but
303	         * we have to allow it on writable replicas to make write commands
304	         * behave consistently.
305	         *
306	         * It's possible that the WRITE flag is set even during a readonly
307	         * command, since the command may trigger events that cause modules to
308	         * perform additional writes. */
309	        int is_ro_replica = server.masterhost && server.repl_slave_ro;
310	        int expire_flags = 0;
311	        if (flags & LOOKUP_WRITE && !is_ro_replica)
312	            expire_flags |= EXPIRE_FORCE_DELETE_EXPIRED;
313	        if (flags & LOOKUP_NOEXPIRE)
314	            expire_flags |= EXPIRE_AVOID_DELETE_EXPIRED;
315	        if (flags & LOOKUP_ACCESS_EXPIRED)
316	            expire_flags |= EXPIRE_ALLOW_ACCESS_EXPIRED;
317	        if (flags & LOOKUP_ACCESS_TRIMMED)
318	            expire_flags |= EXPIRE_ALLOW_ACCESS_TRIMMED;
319	        if (expireIfNeeded(db, key, val, expire_flags) != KEY_VALID) {
320	            /* The key is no longer valid. */
321	            val = NULL;
322	            if (link) *link = NULL;
323	        }
324	    }
325	
326	    if (val) {
327	        /* Update the access time for the ageing algorithm.
328	         * Don't do it if we have a saving child, as this will trigger
329	         * a copy on write madness. */
330	        if (((flags & LOOKUP_NOTOUCH) == 0) &&
331	            (server.current_client && server.current_client->flags & CLIENT_NO_TOUCH) &&
332	            (server.executing_client && server.executing_client->cmd->proc != touchCommand))
333	            flags |= LOOKUP_NOTOUCH;
334	        if (!hasActiveChildProcess() && !(flags & LOOKUP_NOTOUCH)){
335	            if (server.maxmemory_policy & MAXMEMORY_FLAG_LFU) {
336	                updateLFU(val);
337	            } else if (!(server.maxmemory_policy & MAXMEMORY_FLAG_LRM)) {
338	                /* LRM policy should NOT update timestamp on reads. */
339	                val->lru = LRU_CLOCK();
340	            }
341	        }
342	
343	        if (!(flags & (LOOKUP_NOSTATS | LOOKUP_WRITE)))
344	            server.stat_keyspace_hits++;
345	        /* TODO: Use separate hits stats for WRITE */
346	    } else {
347	        if (!(flags & (LOOKUP_NONOTIFY | LOOKUP_WRITE)))
348	            notifyKeyspaceEvent(NOTIFY_KEY_MISS, "keymiss", key, db->id);
349	        if (!(flags & (LOOKUP_NOSTATS | LOOKUP_WRITE)))
350	            server.stat_keyspace_misses++;
351	        /* TODO: Use separate misses stats and notify event for WRITE */
352	    }
353	
354	    return val;
355	}
